// ============================================================
// AGENT #3 — CONTENT & CREATIVE PRODUCTION
// Tạo content brief tuần mới dựa trên:
// - Top content tuần trước (views, GMV, CVR)
// - Metrics hiện tại từ Dashboard
// - Brief yêu cầu từ team
// Output: Brief kịch bản + hook ideas → Lark Ads Team group
// ============================================================

const today = new Date();
const dayOfWeek = today.getDay(); // 0=Sun, 1=Mon

// Chỉ chạy vào thứ Hai — bỏ qua các ngày khác
if (dayOfWeek !== 1) {
  return [{ json: { skipped: true, reason: 'Content Production chỉ chạy thứ Hai' } }];
}
const dateStr = today.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric' });
const weekStr = `Tuần ${Math.ceil(today.getDate()/7)} - Tháng ${today.getMonth()+1}/${today.getFullYear()}`;

// Helper
const col = (item, idx) => { const obj = item.json||item; return Object.values(obj)[idx]; };
const fmt = (n) => {
  n = parseFloat(n) || 0;
  if (Math.abs(n)>=1e9) return (n/1e9).toFixed(2)+' tỷ';
  if (Math.abs(n)>=1e6) return Math.round(n/1e6)+' tr';
  return Math.round(n).toLocaleString('vi-VN');
};
const pct = (n) => ((parseFloat(n)||0)*100).toFixed(1)+'%';

// --- Read Content Briefs (requests from team) ---
let contentBriefs = [];
try {
  contentBriefs = $('Read Content Brief Sheet').all().map(i => i.json).filter(r => {
    const status = (r['Trạng thái']||r['Status']||'').toLowerCase();
    return status === 'mới' || status === 'cần làm' || status === 'pending';
  });
} catch(e) { contentBriefs = []; }

// --- Read Top Content (best performing videos last 7 days) ---
let topContent = [];
try {
  topContent = $('Read Top Content Sheet').all().map(i => i.json).filter(r => r['Video ID'] || r['video_id'] || r['Link']);
} catch(e) { topContent = []; }

// --- Read MTD Metrics ---
const tongHopRows = $('Read Tong Hop MTD').all();
const metrics = {};
tongHopRows.forEach(item => {
  const name = (col(item, 0)||'').toString().trim();
  if (name) metrics[name] = parseFloat(col(item, 5)) || 0;
});

// --- Detect which products need content boost ---
const needsBoost = [];
// Take Rate > 25% = content/funnel problem
const takeRate = metrics['Ads/DS (Take Rate)'] || 0;
if (takeRate > 0.25) needsBoost.push({ reason: `Take Rate cao ${pct(takeRate)} — cần test creative mới giảm CP/DS`, priority: 'HIGH' });

// Net Profit Margin thấp
const npm = metrics['Net Profit Margin'] || 0;
if (npm < 0.10) needsBoost.push({ reason: `Net Profit Margin chỉ ${pct(npm)} — cần video organic + affiliate để giảm phụ thuộc ads`, priority: 'MEDIUM' });

// --- Extract top performing hooks/formats ---
const topVideos = topContent.slice(0, 10).map(r => ({
  title: r['Tiêu đề']||r['Title']||r['title']||'N/A',
  views: fmt(r['Lượt xem']||r['Views']||r['views']||0),
  gmv: fmt(r['GMV']||r['gmv']||0),
  cvr: r['CVR']||r['cvr']||'N/A',
  hook: r['Hook']||r['hook']||r['Câu hook']||'N/A',
  product: r['Sản phẩm']||r['Product']||r['product']||'N/A',
  format: r['Format']||r['format']||r['Dạng video']||'N/A'
}));

// --- Build week plan context ---
const contentContext = {
  week: weekStr,
  date: dateStr,
  metrics: {
    gmv_mtd: fmt(metrics['Tổng GMV']||0),
    take_rate: pct(takeRate),
    net_profit_margin: pct(npm),
    gmv_ads_mtd: fmt(metrics['GMV Ads']||0)
  },
  needs_boost: needsBoost,
  top_performing_content: topVideos,
  pending_briefs: contentBriefs.slice(0,5),
  brands: ['Beucare', 'Retolab'],
  content_pillars: [
    'Skincare routine buổi sáng/tối',
    'Before/After sản phẩm',
    'Tutorial đúng cách dùng',
    'So sánh vs đối thủ (nhẹ nhàng)',
    'Review KOC/KOL authentic',
    'Livestream highlight + clip ngắn',
    'Educational: thành phần, công dụng'
  ]
};

// --- System + User Prompt for Claude ---
const systemPrompt = `Bạn là Creative Director cho Hecatech — công ty TikTok commerce mỹ phẩm VN với 2 brand chính: Beucare và Retolab.
Nhiệm vụ: Tạo Content Brief tuần này cho team Ads/Creative.
Focus: Video ngắn TikTok, Livestream, và Affiliate content.
Tiêu chí: Hook mạnh trong 3 giây đầu, storytelling authentic, call-to-action rõ ràng.
Viết tiếng Việt, ngắn gọn, actionable — đủ để Creative team bắt tay làm ngay.`;

const userPrompt = `CONTENT PRODUCTION BRIEF — ${weekStr}

Data:
${JSON.stringify(contentContext, null, 2)}

Tạo Content Brief theo format:

🎬 CONTENT BRIEF — ${weekStr}

📊 INSIGHT TỪ DATA
• Top content tuần trước: [video nào đang win và tại sao]
• Cơ hội: [gap hoặc trend chưa khai thác]

🎯 MỤC TIÊU TUẦN NÀY
• KPI: [GMV target từ organic/affiliate]
• Focus brand: [Beucare/Retolab/cả hai]

📋 CONTENT PLAN (6-8 video)

Video 1:
• Hook: "[câu hook mạnh, max 10 từ]"
• Format: [Vertical 9:16 / Duet / Tutorial / Before-After]
• Script outline: [3-4 bullet points]
• CTA: [hành động khán giả cần làm]
• Assign: [Creator/KOC]

[Lặp lại cho Video 2-6]

🔴 URGENT (từ brief của team)
[Xử lý pending briefs nếu có]

💡 HOOK IDEAS ĐỀ XUẤT
[5 câu hook để team test A/B]
1. 
2. 
3. 
4. 
5. 

📅 TIMELINE
• [Ngày] — [Việc cần xong]

Dưới 600 từ.`;

return [{
  json: {
    contentContext,
    hasContent: topContent.length > 0 || contentBriefs.length > 0,
    pendingBriefs: contentBriefs.length,
    claudeRequest: {
      model: 'claude-sonnet-4-6',
      max_tokens: 1800,
      system: systemPrompt,
      messages: [{ role: 'user', content: userPrompt }]
    }
  }
}];

const briefText = $input.first().json?.content?.[0]?.text || '⚠️ Lỗi tạo content brief.';
const ctx = $('Analyze and Build Content Brief').first().json.contentContext;

const larkMessage = { msg_type: 'text', content: { text: briefText } };

// Also build a short summary for CEO (just KPIs + urgent items)
const summaryLines = briefText.split('\n').filter(l =>
  l.includes('KPI') || l.includes('🎯') || l.includes('🔴') || l.includes('📊') || l.includes('URGENT')
).slice(0, 8).join('\n');

const ceoSummary = `📣 CONTENT BRIEF ${ctx.week} đã gửi cho Ads Team.\n\nHighlights:\n${summaryLines}`;

return [
  { json: { url: $vars.LARK_ADS_WEBHOOK_URL,  larkMessage: larkMessage } },
  { json: { url: $vars.LARK_CEO_WEBHOOK_URL,  larkMessage: { msg_type: 'text', content: { text: ceoSummary } } } }
];
